def title_word(word, first=False):
    """Title-case a single word.

    If first is True, the word is capitalized normally.
    Otherwise, the word is title-cased (first letter uppercase, rest lowercase).
    """
    if not word:
        return word
    if first:
        return word.capitalize()
    return word[0].upper() + word[1:].lower() if len(word) > 1 else word.upper()


def title_case(text):
    """Title-case a phrase for display."""
    if not text:
        return text
    words = text.split()
    if not words:
        return text
    result = []
    for i, word in enumerate(words):
        first = (i == 0)
        result.append(title_word(word, first=first))
    return ' '.join(result)
